export function Footer({
  text = "{{text}}",
  layout = "{{layout}}",
  bg = "{{bg}}",
  social = {{social}},
}) {
  const simple = layout === "simple";
  return (
    <footer style={{ fontFamily: "system-ui, sans-serif", fontSize: 13, color: "#FAF7F2", background: bg, padding: "18px 16px 14px", boxSizing: "border-box" }}>
      {!simple && (
        <div style={{ display: "flex", gap: 32, marginBottom: 14 }}>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            <strong style={{ fontSize: 12, opacity: .7 }}>Product</strong>
            <a href="#" style={{ color: "#FAF7F2cc", textDecoration: "none" }}>Features</a>
            <a href="#" style={{ color: "#FAF7F2cc", textDecoration: "none" }}>Pricing</a>
          </div>
          <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
            <strong style={{ fontSize: 12, opacity: .7 }}>Company</strong>
            <a href="#" style={{ color: "#FAF7F2cc", textDecoration: "none" }}>About</a>
            <a href="#" style={{ color: "#FAF7F2cc", textDecoration: "none" }}>Careers</a>
          </div>
        </div>
      )}
      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", paddingTop: simple ? 0 : 12, borderTop: simple ? "none" : "1px solid #FAF7F233", fontSize: 12, opacity: .8 }}>
        <span>{text}</span>
        {social && <span style={{ display: "flex", gap: 10 }}><a href="#" style={{ color: "#FAF7F2cc", textDecoration: "none" }}>X</a><a href="#" style={{ color: "#FAF7F2cc", textDecoration: "none" }}>in</a></span>}
      </div>
    </footer>
  );
}
